PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
CREATE TABLE works (
	id INTEGER NOT NULL, 
	title VARCHAR NOT NULL, 
	description TEXT NOT NULL, 
	tech_stack VARCHAR NOT NULL, 
	github_url VARCHAR, 
	app_url VARCHAR, 
	image_url VARCHAR, 
	created_at DATETIME, started_at DATE, 
	PRIMARY KEY (id)
);
CREATE TABLE users (
	id INTEGER NOT NULL, 
	username VARCHAR NOT NULL, 
	password_hash VARCHAR NOT NULL, 
	role VARCHAR NOT NULL, 
	PRIMARY KEY (id)
);
CREATE TABLE blogs (
	id INTEGER NOT NULL, 
	title VARCHAR(255), 
	url VARCHAR(500), 
	summary TEXT, 
	tags VARCHAR(255), 
	published_at DATE, 
	created_at DATETIME, content TEXT, 
	PRIMARY KEY (id)
);
CREATE TABLE careers (
	id INTEGER NOT NULL, 
	title VARCHAR, 
	company VARCHAR, 
	period VARCHAR, 
	description TEXT, 
	technologies TEXT, start_date DATE, end_date DATE, 
	PRIMARY KEY (id)
);
CREATE TABLE posts (
	id INTEGER NOT NULL, 
	title VARCHAR, 
	content VARCHAR, 
	task_type VARCHAR, 
	start_time DATETIME, 
	end_time DATETIME, 
	work_time_minutes INTEGER, 
	work_id INTEGER, 
	created_at DATETIME, 
	PRIMARY KEY (id), 
	FOREIGN KEY(work_id) REFERENCES works (id)
);
CREATE INDEX ix_works_id ON works (id);
CREATE INDEX ix_users_id ON users (id);
CREATE UNIQUE INDEX ix_users_username ON users (username);
CREATE INDEX ix_careers_id ON careers (id);
CREATE INDEX ix_posts_id ON posts (id);
COMMIT;
